cat > main.tf <<'EOF'
terraform {
  required_version = "= 1.16.0"
  required_providers {
    google = { source = "hashicorp/google", version = "~> 7.0" }
  }
  backend "gcs" {}
}
variable "project" { type = string }
variable "region" { type = string }
variable "image" { type = string }
variable "runtime_sa" { type = string }
provider "google" {
  project = var.project
  region  = var.region
}
resource "google_cloud_run_v2_service" "lab" {
  name                = "devopps-w39"
  location            = var.region
  deletion_protection = false
  ingress             = "INGRESS_TRAFFIC_ALL"
  template {
    service_account = var.runtime_sa
    scaling {
      min_instance_count = 0
      max_instance_count = 1
    }
    containers {
      image   = var.image
      command = ["python", "-m", "uvicorn"]
      args    = ["reference.stage03:app", "--host", "0.0.0.0", "--port", "8000"]
      ports { container_port = 8000 }
      resources {
        limits = { cpu = "1", memory = "512Mi" }
        cpu_idle = true
      }
      startup_probe {
        http_get { path = "/livez" }
        period_seconds = 3
        failure_threshold = 10
      }
    }
  }
}
output "service_url" { value = google_cloud_run_v2_service.lab.uri }
EOF
