cat > install-terraform.py <<'PY'
import hashlib,io,pathlib,platform,urllib.request,zipfile
version="1.16.0"
assert platform.machine() in ("x86_64","amd64"), "Use a Linux amd64 runner for this lab"
name=f"terraform_{version}_linux_amd64.zip"
base=f"https://releases.hashicorp.com/terraform/{version}/"
data=urllib.request.urlopen(base+name,timeout=30).read()
sums=urllib.request.urlopen(base+f"terraform_{version}_SHA256SUMS",timeout=30).read().decode()
expected=next(line.split()[0] for line in sums.splitlines() if line.split()[-1]==name)
assert hashlib.sha256(data).hexdigest()==expected, "checksum mismatch"
with zipfile.ZipFile(io.BytesIO(data)) as z:
    pathlib.Path("terraform").write_bytes(z.read("terraform"))
pathlib.Path("terraform").chmod(0o755)
PY
printf '\nterraform\n' >> .gitignore
python3 install-terraform.py
./terraform init -backend=false
./terraform fmt
./terraform validate

python3 - <<'PY'
from copy import deepcopy
expected = {"issuer": "https://gitlab.com", "audience": "devopps-lab", "project": "my-lab", "branch": "main", "protected": True}
def conditions_match(claims):
    return all(claims.get(key) == value for key, value in expected.items())
cases = [("intended", deepcopy(expected), True)]
for key, value in (("issuer", "https://other.invalid"), ("audience", "other"), ("project", "fork"), ("branch", "feature"), ("protected", False)):
    wrong = deepcopy(expected)
    wrong[key] = value
    cases.append(("wrong-" + key, wrong, False))
for label, claims, wanted in cases:
    result = conditions_match(claims)
    if result != wanted:
        raise SystemExit("FAILED: " + label)
    print(label + ": " + ("allowed" if result else "denied"))
print("Condition exercise only: these dictionaries are NOT verified tokens.")
PY
